--shadow-none: none;
--shadow-sm: 0 1px 2px rgba(0,0,0,0.40);
--shadow-md: 0 2px 8px rgba(0,0,0,0.48);
--shadow-lg: 0 8px 24px rgba(0,0,0,0.56);
--shadow-xl: 0 16px 40px rgba(0,0,0,0.64);
--duration-fast: 80ms;
--duration-base: 200ms;
--duration-slow: 350ms;
--ease-out: cubic-bezier(0.4, 0, 0.2, 1);
--ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
}
:root {
  /* Primary - Slack Aubergine (사이드바, brand mark) — 다크 기본 */
  --color-primary-50:  #1F0520;
  --color-primary-100: #2A082B;
  --color-primary-200: #350B36;
  --color-primary-300: #3F0E40;
  --color-primary-400: #4A154B;  /* Slack Aubergine */
  --color-primary-500: #6B336B;  /* 다크에서 본체로 끌어올린 강조 */
  --color-primary-600: #926692;  /* dark sidebar accent / brand mark */
  --color-primary-700: #B999B9;
  --color-primary-800: #E0CCE0;
  --color-primary-900: #F4ECF4;

  /* Secondary - Slack Action Blue (다크에서 한 단계 밝게) */
  --color-secondary-500: #4BA4E3;

  /* Slack 4색 액센트 (hash 로고) — 브랜드 hue 유지 */
  --slack-cyan:   #36C5F0;
  --slack-green:  #2EB67D;
  --slack-yellow: #ECB22E;
  --slack-red:    #E01E5A;

  /* Neutral - 다크 반전 램프 (0 = 가장 어두움) */
  --color-neutral-0:    #0E0E10;
  --color-neutral-50:   #16181C;
  --color-neutral-100:  #1A1D21;   /* main canvas */
  --color-neutral-200:  #222529;
  --color-neutral-300:  #2C2D30;
  --color-neutral-500:  #565759;
  --color-neutral-700:  #ABABAD;
  --color-neutral-800:  #D1D2D3;
  --color-neutral-900:  #E8E8E9;
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크 위에서 가독성 확보 */
  --color-success-bg: #133029;
  --color-success-fg: #2BAC76;
  --color-warning-bg: #322611;
  --color-warning-fg: #E0A33A;
  --color-error-bg:   #381822;
  --color-error-fg:   #F1547F;
  --color-info-bg:    #122E40;
  --color-info-fg:    #4BA4E3;

  /* Surface */
  --bg-base:     #1A1D21;          /* main canvas */
  --bg-subtle:   #222529;
  --bg-elevated: #2C2D30;
