  /* Text */
  --text-primary:    #E6E6E6;
  --text-secondary:  #ABABAD;
  --text-tertiary:   #868686;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #565759;

  /* Border */
  --border-default: #2C2D30;
  --border-subtle:  #222529;
  --border-strong:  #44464A;
  --border-focus:   #4BA4E3;
}

